const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function nextBigInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0n;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10n + BigInt(buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const pBig = nextBigInt();
    if (pBig === null) return;
    const P = Number(pBig);

    const out = [];

    for (let i = 0; i < P; i++) {
        const L = nextBigInt();
        const A = nextBigInt();
        const B = nextBigInt();

        let low = 0n;
        let high = B - A;
        const maxM = 5000000n;
        if (high > maxM) {
            high = maxM;
        }

        let ans = 0n;
        while (low <= high) {
            const mid = (low + high) >> 1n;
            const sum = mid * A + (mid * (mid - 1n)) / 2n;
            if (sum < L) {
                ans = mid;
                low = mid + 1n;
            } else {
                high = mid - 1n;
            }
        }

        out.push((ans + 1n).toString());
    }

    console.log(out.join('\n'));
}

solve();
